// User-facing text of the verdict engine (judge.js, parse.js), in every supported language.
// A message is either a string with {name} placeholders or a function (vars) => string
// for plurals and conditional wording. Both languages must have the same keys.

export const LANGS = ['en', 'ko'];

// "1 file", "3 files"
function count(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

