export const MESSAGES = { en, ko };

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// A date from the data files (2026-12-31) as the language writes it: "31 December 2026", "2026년 12월 31일".
export function formatDate(iso, lang) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
  if (!m) return String(iso || '');
  const [year, month, day] = [Number(m[1]), Number(m[2]), Number(m[3])];
  return lang === 'ko' ? `${year}년 ${month}월 ${day}일` : `${day} ${MONTHS[month - 1]} ${year}`;
}

const has = (table, key) => Object.prototype.hasOwnProperty.call(table, key);

// Returns t(key, vars) for the language. Unknown languages use English, and so does a key
// missing in the language. A key missing everywhere, or a placeholder with no value, throws.
export function translator(lang) {
  const table = LANGS.includes(lang) ? MESSAGES[lang] : MESSAGES.en;
  return function t(key, vars = {}) {
    const msg = has(table, key) ? table[key] : has(MESSAGES.en, key) ? MESSAGES.en[key] : undefined;
    if (msg === undefined) throw new Error('Missing message: ' + key);
    if (typeof msg === 'function') return msg(vars);
    return msg.replace(/\{(\w+)\}/g, (_, name) => {
      const value = vars[name];
      if (value === undefined || value === null) throw new Error(`Missing value {${name}} for message: ${key}`);
      return String(value);
    });
  };
}
